int visorchannel_signalinsert ( struct visorchannel * channel , u32 queue , void * msg ) { int rc ; cfs_time_t flags ; if ( channel -> needs_lock ) { spin_lock_irqsave ( & channel -> insert_lock , flags ) ; rc = signalinsert_inner ( channel , queue , msg ) ; spin_unlock_irqrestore ( & channel -> insert_lock , flags ) ; } else { rc = signalinsert_inner ( channel , queue , msg ) ; } return rc ; } 